import json,gzip,hashlib
from pathlib import Path
freeze=json.loads(Path('calibration/simulator-078/rule-freeze-002.json').read_text());seal=json.loads(Path('calibration/simulator-078/review-seal.json').read_text());raw=gzip.decompress(Path('calibration/simulator-078/blind-judgments.json.gz').read_bytes());assert hashlib.sha256(raw).hexdigest()==seal['sha256']
for p,h in freeze['files'].items():assert hashlib.sha256(Path(p).read_bytes()).hexdigest()==h,p
mapping=json.loads(Path('calibration/simulator-078/blind-map.json').read_text());blind=json.loads(raw)['judgments'];manifest=json.loads(gzip.decompress(Path('calibration/executor-077/manifest.json.gz').read_bytes()));out=[]
for r in mapping:
 j=blind[r['id']];q=manifest['definitions'][r['questionIndex']];oldA=r['AExecutor']=='existing';pref=r['AExecutor']if j['choice']=='A'else('existing'if r['AExecutor']=='grok'else'grok')if j['choice']=='B'else j['choice'];out.append({**r,**j,'preferredExecutor':pref,'existingVerdict':j['aVerdict']if oldA else j['bVerdict'],'grokVerdict':j['bVerdict']if oldA else j['aVerdict'],'prompt':q['prompt'],'usedForAuthoring':r['id']in freeze['authoringIds']})
summary={}
for cohort in ['all','development','holdout','holdout049','holdout056','grok075']:
 rs=[r for r in out if (r['cohort']!='grok075'if cohort=='all'else r['cohort']==cohort)];summary[cohort]={'profiles':len(set(r['modelId']for r in rs)),'items':len(rs),**{k:sum(r['preferredExecutor']==k for r in rs)for k in ['existing','grok','both','neither','unresolved']},'existingOverreach':sum(r['existingVerdict']=='overreach'for r in rs),'grokOverreach':sum(r['grokVerdict']=='overreach'for r in rs)}
result={'reviewType':seal['type'],'ruleFreezeSHA256':hashlib.sha256(Path('calibration/simulator-078/rule-freeze-002.json').read_bytes()).hexdigest(),'sample':{'profiles':192,'items':384},'summary':summary,'limits':['Executor labels and all career outcomes were hidden from the fresh AI reviewer. A/B orientation shuffled independently for each question.','Diagnostic sample of changed-result profiles, two questions each; not a population accuracy estimate. Profile clusters, ties, neither and unresolved are retained.','Same provider as one answer executor; no independent human or student validation.',f"Only {freeze['authoringItems']} available original-development items from {freeze['authoringProfiles']} profiles informed rules. Later development and all evaluation judgments stayed uninspected until the rules froze. Original holdouts have been inspected historically.",'A third repaired answer, when different from both reviewed choices, has not itself received an independent blinded judgment.'], 'judgments':out}
Path('research/simulator-078/blinded-review.json').write_text(json.dumps(result,separators=(',',':')));print(json.dumps(summary,indent=2))
